using Godot;
using System;
using System.Text;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class ImageWorkspaceOperations
{
    private static GArray AvailableEffects()=>GD.Load<GDScript>("res://Workspaces/ImageWorkspace/image_workspace.gd").GetScriptConstantMap()["AVAILABLE_EFFECTS"].AsGodotArray();
    private GArray EffectChoices(Control owner,string filter,bool readable){var choices=new GArray();foreach(var value in AvailableEffects()){string kind=value.AsString(),title=(readable?kind.Replace("_"," "):kind).Capitalize();if(title.Contains(filter,StringComparison.OrdinalIgnoreCase))choices.Add(MenuEntry(title,Callable.From(()=>add_effect(owner,kind))));}if("canvas shader".Contains(filter,StringComparison.OrdinalIgnoreCase))choices.Add(MenuEntry("Canvas shader…",new Callable(owner,"_choose_shader_effect")));return choices;}
    private GArray StyleChoices(Control owner,bool links)
    {
        var choices=new GArray();if(!links){choices.Add(MenuEntry("Soft shadow",Callable.From(()=>add_effect(owner,"shadow"))));choices.Add(MenuEntry("Sticker outline",Callable.From(()=>add_effect(owner,"outline"))));choices.Add(MenuEntry("Monochrome",Callable.From(()=>add_effect(owner,"grayscale"))));}choices.Add(MenuEntry("Copy style",Callable.From(()=>copy_style(owner))));choices.Add(MenuEntry("Paste style",Callable.From(()=>paste_style(owner))));choices.Add(MenuEntry("Save current style…",Callable.From(()=>save_style(owner))));var presets=owner.Get("_presets").AsGodotDictionary();foreach(var key in presets.Keys){string name=key.AsString();choices.Add(MenuEntry(name,Callable.From(()=>apply_style_preset(owner,name,false))));if(links)choices.Add(MenuEntry("Link: "+name,Callable.From(()=>apply_style_preset(owner,name,true))));}return choices;
    }
    private void EffectCard(Control owner,Node parent,Resource layer,int index,bool dock)
    {
        var effects=layer.Get("effects").AsGodotArray();var effect=effects[index].AsGodotDictionary();var panel=new PanelContainer();panel.AddThemeStyleboxOverride("panel",box(new Color("111c28"),new Color(dock?"304a5c":"304252"),6,7));parent.AddChild(panel);var fields=new VBoxContainer();if(dock)fields.AddThemeConstantOverride("separation",5);panel.AddChild(fields);var header=new HBoxContainer();fields.AddChild(header);string type=effect["type"].AsString();var enabled=new CheckButton{Text=(dock?type.Replace("_"," "):type).Capitalize(),ButtonPressed=Get(effect,"enabled",true).AsBool(),SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};header.AddChild(enabled);enabled.Toggled+=value=>Action(owner,()=>effect["enabled"]=value);var actions=dock?new HBoxContainer():header;if(!dock){button(owner,header,"↑",Callable.From(()=>move_effect(owner,index,-1)),"Move effect earlier","");button(owner,header,"↓",Callable.From(()=>move_effect(owner,index,1)),"Move effect later","");button(owner,header,"Apply",Callable.From(()=>owner.Call("_apply_effect",layer,index)),"Bake effects through this point into layer pixels","");}button(owner,header,"×",Callable.From(()=>Action(owner,()=>effects.RemoveAt(index))),"Remove effect","");effect_fields(owner,fields,effect);if(dock){fields.AddChild(actions);button(owner,actions,"Apply",Callable.From(()=>owner.Call("_apply_effect",layer,index)),"Bake effects through this point into layer pixels","");button(owner,actions,"↑",Callable.From(()=>move_effect(owner,index,-1)),"Move effect earlier","");button(owner,actions,"↓",Callable.From(()=>move_effect(owner,index,1)),"Move effect later","");}
    }
    public void build_effects(Control owner,Resource layer){var effects=section(owner,"Effects");effect_selection_control(owner,effects,layer);menu(owner,effects,"+ Add effect",EffectChoices(owner,"",false));menu(owner,effects,"Style presets",StyleChoices(owner,false));for(int i=0;i<layer.Get("effects").AsGodotArray().Count;i++)EffectCard(owner,effects,layer,i,false);}
    public void build_effects_dock(Control owner)
    {
        var dock=owner.Get("_effects_dock").As<VBoxContainer>();dock.Name="EffectsDock";dock.AddThemeConstantOverride("separation",6);var header=new HBoxContainer();dock.AddChild(header);var title=new Label{Text="EFFECTS & STYLES",SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};title.AddThemeFontSizeOverride("font_size",12);title.AddThemeColorOverride("font_color",new Color("77e4c7"));header.AddChild(title);button(owner,header,"×",new Callable(owner,"_toggle_effects_panel"),"Return to layer properties","");var search=owner.Get("_effects_search").As<LineEdit>();search.Name="EffectsSearch";search.PlaceholderText="Search effects…";search.ClearButtonEnabled=true;dock.AddChild(search);search.TextChanged+=value=>{owner.Set("_effects_filter",value);refresh_effects_dock(owner);};var scroll=owner.Get("_effects_scroll").As<ScrollContainer>();scroll.Name="EffectsScroll";scroll.SizeFlagsVertical=Control.SizeFlags.ExpandFill;scroll.HorizontalScrollMode=ScrollContainer.ScrollMode.Disabled;scroll.VerticalScrollMode=ScrollContainer.ScrollMode.ShowAlways;dock.AddChild(scroll);var content=owner.Get("_effects_content").As<VBoxContainer>();content.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;content.AddThemeConstantOverride("separation",8);scroll.AddChild(content);
    }
    public void refresh_effects_dock(Control owner)
    {
        if(!owner.Get("_effects_open").AsBool())return;var layer=main_layer(owner);string filter=owner.Get("_effects_filter").AsString();var signature=new StringBuilder(Document(owner).GetInstanceId().ToString()).Append(filter).Append(layer?.Get("id").AsString()??"");if(layer!=null)foreach(var value in layer.Get("effects").AsGodotArray()){var effect=value.AsGodotDictionary();signature.Append(Get(effect,"id","").AsString()).Append(effect["type"].AsString());if(ResourceValue(Get(effect,"curve")) is Curve curve)signature.Append(curve.GetInstanceId());}string stamp=signature.ToString();if(stamp==owner.Get("_effects_signature").AsString())return;owner.Set("_effects_signature",stamp);var scroll=owner.Get("_effects_scroll").As<ScrollContainer>();int oldScroll=scroll.ScrollVertical;var content=owner.Get("_effects_content").As<VBoxContainer>();clear(content);if(layer==null){content.AddChild(new Label{Text="Select a layer to edit its effects.",AutowrapMode=TextServer.AutowrapMode.WordSmart});return;}var label=new Label{Text=layer.Get("label").AsString(),ClipText=true};label.AddThemeColorOverride("font_color",new Color("9db3c6"));content.AddChild(label);effect_selection_control(owner,content,layer);var choices=EffectChoices(owner,filter,true);menu(owner,content,"＋ Add effect",choices).Disabled=choices.Count==0;int visible=0;var effects=layer.Get("effects").AsGodotArray();for(int i=0;i<effects.Count;i++){string title=effects[i].AsGodotDictionary()["type"].AsString().Replace("_"," ").Capitalize();if(!title.Contains(filter,StringComparison.OrdinalIgnoreCase))continue;visible++;EffectCard(owner,content,layer,i,true);}if(visible==0){var empty=new Label{Text=filter.Length>0?"No matching effects.":"Add an effect to get started."};empty.AddThemeColorOverride("font_color",new Color("8fa8bb"));content.AddChild(empty);}menu(owner,content,"Style presets",StyleChoices(owner,true));scroll.SetDeferred("scroll_vertical",oldScroll);
    }
    public void create_adjustment_group(Control owner)
    {
        if(_documents.selected_roots(Document(owner),Canvas(owner).Get("selected").AsGodotArray()).Count==0)return;group_selected(owner);var group=main_layer(owner);if(group==null)return;group.Set("label","Adjustment group");add_effect(owner,"brightness");owner.Call("_set_tool","effects");open_stack_editor(owner,false);
    }
}
